"""Every bonus CI lane is generated by tools/test-tiers.py, never hand-listed.

A bonus lane converges core + one manifest `stack:` (ruling 2026-10-15). A hand
list drifts: a role added to the manifest would get no lane and no path filter,
and its stack would go untested quietly. So the workflow matrix is the tool's
output, every anatomy test has exactly one tier, and the security, contract,
gitleaks and lockfile gates sit in T0, which runs on every push.
"""
from __future__ import annotations

import importlib.util
import pathlib
import re

import yaml

REPO = pathlib.Path(__file__).resolve().parents[2]
CI = REPO / ".github" / "workflows" / "ci.yml"
TOOL = REPO / "tools" / "test-tiers.py"
ALWAYS = re.compile(r"secur|secret|contract|lockfile|gitleak")


def _tiers():
    assert TOOL.is_file(), "tools/test-tiers.py (the lane derivation) does not exist"
    spec = importlib.util.spec_from_file_location("_nos_test_tiers", TOOL)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def _jobs() -> dict:
    return yaml.safe_load(CI.read_text(encoding="utf-8"))["jobs"]


def _runs(job: dict) -> str:
    return "\n".join(str(s.get("run", "")) for s in job.get("steps") or [])


def test_the_bonus_matrix_is_the_tools_output() -> None:
    jobs = _jobs()
    pick = [n for n, j in jobs.items() if "tools/test-tiers.py --select" in _runs(j)]
    assert len(pick) == 1, f"one job must pick the lanes with tools/test-tiers.py --select, found {pick}"
    bonus = [n for n, j in jobs.items()
             if f"needs.{pick[0]}.outputs" in str((j.get("strategy") or {}).get("matrix"))]
    assert len(bonus) == 1, "no job takes its matrix from the picker's output"
    job = jobs[bonus[0]]
    matrix = job["strategy"]["matrix"]
    assert set(matrix) == {"include"} and "fromJSON(" in str(matrix["include"]), (
        f"the bonus matrix is not exactly fromJSON(<picker output>): {matrix}")
    assert job["strategy"].get("fail-fast") is False, "fail-fast would cancel one stack for another's red"
    assert "--nightly" in _runs(jobs[pick[0]]), "the picker has no nightly rotation"
    run = _runs(job)
    assert "-e @profiles/core.yml" in run and "matrix.flags" in str(job), (
        "a bonus lane must converge core plus the flags the tool derived")


def test_every_stack_outside_core_has_one_lane_and_its_paths() -> None:
    t = _tiers()
    lanes = t.derive()["lanes"]
    rows = yaml.safe_load((REPO / "state" / "manifest.yml").read_text(encoding="utf-8"))["services"]
    core = t.core_flags()
    want = {r["stack"] for r in rows if r.get("stack") and r.get("install_flag") not in core}
    assert set(lanes) == want, f"lanes {sorted(lanes)} != stacks outside core {sorted(want)}"
    for r in rows:
        if r.get("stack") in lanes and r.get("install_flag") not in core:
            lane = lanes[r["stack"]]
            assert r["install_flag"] in lane["flags"], f"{r['id']}: its flag is not in the {r['stack']} lane"
            if (REPO / "roles" / f"pazny.{r['id']}").is_dir():
                assert f"roles/pazny.{r['id']}/" in lane["paths"], f"{r['id']}: its role has no path filter"
    for name, lane in lanes.items():
        lost = [p for p in lane["paths"] if not (REPO / p).exists()]
        assert lane["paths"] and not lost, f"{name}: no paths, or paths that do not exist: {lost}"


def test_every_anatomy_test_has_exactly_one_tier() -> None:
    d = _tiers().derive()
    files = sorted(p.name for p in (REPO / "tests" / "anatomy").glob("test_*.py"))
    tiers = d["tests"]
    assert sorted(tiers) == files, "a test file has no tier, or a tier names a file that is gone"
    bad = {f: v for f, v in tiers.items() if v not in {"T0", "core", *d["lanes"]}}
    assert not bad, f"unknown tiers: {bad}"


def test_security_contract_gitleaks_lockfile_gates_are_t0() -> None:
    tiers = _tiers().derive()["tests"]
    assert tiers.get("test_lockfile_sync.py") == "T0" and tiers.get("test_gitleaks_scan_command.py") == "T0"
    moved = {f: v for f, v in tiers.items() if ALWAYS.search(f) and v != "T0"}
    assert not moved, f"an always-on gate left T0: {moved}"


def test_a_changed_role_picks_its_lane_and_a_week_covers_all() -> None:
    t = _tiers()
    lanes = set(t.derive()["lanes"])
    assert [x["stack"] for x in t.select(["roles/pazny.gitea/tasks/main.yml"])] == ["devops"]
    assert t.select(["README.md", "tests/anatomy/conftest.py"]) == []
    week = {x["stack"] for day in range(7) for x in t.nightly(day)}
    assert week == lanes, f"the rotation never runs {sorted(lanes - week)}"
